"""Data files the app needs (index.html, PNGs).

A file on the filesystem always wins, so it can be replaced on the device.
Otherwise the copy built into the firmware is used (see firmware/), which
lives in flash and costs no RAM.
"""
import os

try:
    # generated by firmware/mkassets.py, only exists in the firmware
    from frozen_assets import FILES as _FROZEN
except ImportError:
    _FROZEN = {}


def get(name):
    """Return the built-in contents of name as bytes, or None if the file on
    the filesystem should be used instead."""
    try:
        os.stat(name)
        return None
    except OSError:
        return _FROZEN.get(name)


def open_png(png, name):
    """Open name with a pngdec.PNG, from the filesystem or the firmware"""
    data = get(name)
    if data is None:
        png.open_file(name)
    else:
        png.open_RAM(data)
